protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        LocalDateTime startTime = LocalDateTime.ofEpochSecond(start / 1000, (int) (start % 1000), 0);
        LocalDateTime endTime = LocalDateTime.ofEpochSecond(end / 1000, (int) (end % 1000), 0);

        while (startTime.isBefore(endTime.plusMillis(FETCH_DATA_DURATION))) {
            TimeRange timeRange = TimeRange.of(startTime, endTime);
            timeRanges.add(timeRange);
            startTime = endTime.plusMillis(1);
        }

        return timeRanges;
    }

protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        // Implement the logic to split time ranges based on the FETCH_DATA_DURATION
        // Example:
        if ((end - start) > FETCH_DATA_DURATION) {
            timeRanges.add(new TimeRange(start, FETCH_DATA_DURATION));
            long remainingTime = end - start - FETCH_DATA_DURATION;
            while (remainingTime > FETCH_DATA_DURATION) {
                timeRanges.add(new TimeRange(start + FETCH_DATA_DURATION, FETCH_DATA_DURATION));
                remainingTime -= FETCH_DATA_DURATION;
            }
        } else {
            timeRanges.add(new TimeRange(start, end));
        }
        return timeRanges;
    }

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate input parameters
    if (start >= end || start < 0 || end > Long.MAX_VALUE) {
        throw new IllegalArgumentException("Invalid time range: start=" + start + ", end=" + end);
    }

    // Calculate the duration
    long duration = end - start;

    // Determine the number of time ranges to split
    long numRanges = Math.max(1, (int) Math.ceil((double) duration / FETCH_DATA_DURATION));

    // Calculate the size of each time range
    long rangeSize = duration / numRanges;

    // Initialize the list of time ranges
    List<TimeRange> timeRanges = new ArrayList<>(numRanges);

    // Split the time range into multiple time ranges
    for (int i = 0; i < numRanges; i++) {
        long startRange = start + i * rangeSize;
        long endRange = Math.min(start + (i + 1) * rangeSize, end);
        if (startRange < endRange) {
            timeRanges.add(new TimeRange(startRange, endRange));
        }
    }

    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> timeRanges = new ArrayList<>();
    // Calculate the duration of one time range
    long duration = Math.max(0, end - start);
    // Determine the number of time ranges based on the FETCH_DATA_DURATION
    int numRanges = Math.min(10, (int) Math.ceil(duration / FETCH_DATA_DURATION));
    // Create the time ranges
    for (int i = 0; i < numRanges; i++) {
        long startTime = start + i * FETCH_DATA_DURATION;
        long endTime = Math.min(end, start + (i + 1) * FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(startTime, endTime));
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){
    // Ensure start and end time is smaller than FETCH_DATA_DURATION
    if ( Math.abs(end - start) > FETCH_DATA_DURATION ) {
        // Split the time range into smaller time ranges
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        long currentEnd = Math.min(end, start + FETCH_DATA_DURATION);
        while (currentEnd <= end) {
            timeRanges.add(new TimeRange(currentStart, currentEnd - 1));
            currentStart = currentEnd;
            currentEnd += FETCH_DATA_DURATION - 1;
            if (currentEnd > end) {
                currentEnd = end;
            }
        }
        return timeRanges;
    } else {
        // No need to split, return the single time range
        return Collections.singletonList(new TimeRange(Math.round(start), Math.round(end)));
    }
}

