static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    return timeBucket / dayStep;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep == 0) {
        return timeBucket;
    }
    long startBucket = timeBucket - ((timeBucket % dayStep) + dayStep - 1) % dayStep;
    return startBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    intbruary = timeBucket % 1000;
    month = (timeBucket -bruary) / 1000;
    year = (timeBucket - month * 1000 -bruary) / 1000;
    if (dayStep < 2) return timeBucket + (dayStep - 1) * (1000 * 1000 * 1000);
    int lastMonth = timeBucket % (dayStep * 1000 * 1000 * 1000);
    int endOfMonth = lastMonth + (31 - lastMonth % 31)
            + (lastMonth % 31 == 0 ? 28 : 0)
            + (lastMonth % 31 == 29 ? 29 : 0)
            + (lastMonth % 31 == 30 ? 30 : 0);
    if (lastMonth >= endOfMonth) beginOfMonth = lastMonth - (endOfMonth - lastMonth);
    else beginOfMonth = lastMonth;
    return year * 1000000000L + month * 10000000 + beginOfMonth * 1000;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long startOfYear = 2000; // Base year for the compression
    long currentYear = startOfYear + timeBucket / 8765; // Calculate the current year based on time bucket
    long compressedDateTime = (currentYear - startOfYear) * dayStep; // Calculate the compressed date and time in days
    return compressedDateTime;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the lower bound of the time bucket
    long lowerBound = timeBucket - (timeBucket % dayStep);
    return lowerBound;
}

