        if (ch < 0x80) {
            result++;
            current++;
        } else if (ch < 0xc0) {
            result += 2;
            current += 1;
        } else if (ch < 0xe0) {
            result += 3;
            current += 2;
        } else {
            result += 4;
            current += 3;
        }
    }
    return result;
}

