        } else if (asciiCodePoint < 2097152) {
            size += 5;
        } else if (asciiCodePoint < 4194304) {
            size += 6;
        } else if (asciiCodePoint < 1073741824) {
            size += 7;
        } else {
            size += 8; // U+10000 to U+10FFFF: 4 bytes
        }
    }

    return size;
}

