private void pop(final String descriptor) throws java.lang.ArrayIndexOutOfBoundsException {
    int argsCount = 0;
    int cutLength = 0;

    for (int i = 0; i < descriptor.length(); i++) {
        if (descriptor.charAt(i) == '(') {
            argsCount++;
        } else if (descriptor.charAt(i) == ')') {
            argsCount--;
            cutLength++;
        } else if (argsCount == 0 && descriptor.charAt(i) == ';') {
            return;
        }
    }

    if (argsCount != 0 || cutLength == 0) {
        throw new ArrayIndexOutOfBoundsException("Incorrect descriptor format");
    }

    int skipSpace = 0;

    for (int index = 0; index < descriptor.length(); index++) {
        if (descriptor.charAt(index) == '_') {
            skipSpace = index + 1;
            continue;
        } else if (descriptor.charAt(index) == '(') {
            argsCount++;
        } else if (descriptor.charAt(index) == ')') {
            argsCount--;
            break;
        } else if (argsCount == 0 && descriptor.charAt(index) == ';') {
            break;
        }
    }

    String[] args = new String[argsCount];

    for (int i = 0; i < argsCount; i++) {
        int j = skipSpace;
        for (; j < descriptor.length(); j++) {
            if (descriptor.charAt(j) == ',' || descriptor.charAt(j) == ')' || i == argsCount - 1) {
                args[i] = descriptor.substring(skipSpace, j);
                skipSpace = j + 1;
                break;
            }
        }
    }

    // Do something with the popped types
    for (String arg : args) {
        System.out.println(" popping " + arg);
    }
}

