    double midPoint = box.getMinX() + (box.getMaxX() - box.getMinX()) / 2.0;

    // Create a new Box2D for the left part
    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), midPoint, box.getHeight());

    // Create a new Box2D for the right part
    Box2D rightBox = new Box2D(midPoint, box.getMinY(), box.getMaxX(), box.getHeight());

    // Return the pair of boxes
    return new Pair<>(leftBox, rightBox);
}

