public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    DenseObjectIterator<ByteRef> it = node.iterator();
    int count = 0;

    while (it.hasNext()) {
        out.writeByte(it.next().ref.get());
        it.next().ref.get();
        count++;
    }
    return count;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    // Write header information
    if (node.getHeader() != null) {
        out.writeUTF(node.getHeader());
    }
    // Write array data
    for (int i = 0; i < node.getElements().length; i++) {
        out.write(node.getElements()[i]);
        totalSize += node.getElements()[i].length;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out,LinkedBuffer node) throws IOException {
  // Write the linked buffer content to the DataOutput
  out.writeLong(node.getSize());
  out.writeLong(node.getSize());
  out.writeByte(node.getSize());
  out.writeByte(node.getSize());
  for (int i = 0; i < node.getContent().length; i++) {
    out.writeByte(node.getContent()[i]);
  }
  return node.getContent().length;
}

public static int writeTo( DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    for (byte[] buffer : node.getBuffers()) {
        totalSize += writeBuffer(out, buffer);
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null || out == null) {
        throw new IllegalArgumentException("Node or DataOutput cannot be null.");
    }
    int contentSize = 0;
    // Write node details into DataOutput
    out.writeUTF(node.getStringAttribute("name"));
    out.write(node.getIntegerAttribute("size"));
    contentSize += node.getAttributeSize();
    // Write nodes in the LinkedBuffer recursively
    for (LinkedBuffer child : node.getChildren()) {
        contentSize += writeTo(out, child);
    }
    return contentSize;
}

