                currentNode = currentNode.getParent();
            }

            if (currentNode != null && isBoundaryMatch(predicate, currentNode)) {
                if (dir == TreeTraversal.DOWN) {
                    return new OuterFaceCirculator(currentNode, TreeTraversal.UP, currentNode.getLeft(), currentNode.getRight());
                } else if (dir == TreeTraversal.UP) {
                    return new OuterFaceCirculator(currentNode, TreeTraversal.DOWN, currentNode.getLeft(), currentNode.getRight());
