private String unescapeId(String input){
    StringBuilder sb = new StringBuilder();
    for(int i = 0; i < input.length(); i++){
        if(input.charAt(i) == '\\'){
            if(i+1 < input.length()){
                char nextChar = input.charAt(i+1);
                switch(nextChar){
                    case 'b':
                        sb.append('\b');
                        break;
                    case 't':
