    while (from < to) {
        V temp = arr[from];
        arr[from++] = arr[to];
        arr[to--] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }

    if (from < 0 || from >= arr.length) {
        throw new IndexOutOfBoundsException("Starting index out of range");
    }

    if (to < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("Ending index out of range");
    }

    if (from >= to) {
        return;
    }

    int i = from;
    int j = to - 1;

    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range");
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

public static final <V> void reverse(final V[] arr, int from, int to) {
    int mid = (from + to) / 2;
    for (int i = from; i <= mid; i++) {
        V temp = arr[i];
        arr[i] = arr[to - (i - from) - 1];
        arr[to - (i - from) - 1] = temp;
    }
}

