private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    int n = vertices.size();
    if (n <= 1) return true; // A clique with 0 or 1 vertex is always a clique.

    for (V v1 : vertices) {
        Set<V> neighbors = new HashSet<>();
        for (E e : graph.edgesOf(v1)) {
            V v2 = graph.negEdge(e);
            if (!vertices.contains(v2)) {
                neighbors.add(v2);
            }
        }

        if (neighbors.size() < n - 1) {
            return false; // If the induced subgraph has fewer than n-1 neighbors, it's not a clique.
        }
    }

    return true; // If all vertices have at least n-1 neighbors, the induced subgraph is a clique.
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    Set<V> remainingVertices = graph.vertexSet();
    remainingVertices.removeAll(vertices);

    // If there are no more vertices left, the subgraph is a clique
    if (remainingVertices.isEmpty()) {
        return true;
    }

    for (V vertex: vertices) {
        if (!graph.containsEdge(vertex)) {
            // If any vertex cannot find an edge, the subgraph is not a clique
            return false;
        }
    }

    // Check if all vertices adjacent to any vertex have an edge
    for (V vertex: remainingVertices) {
        Set<V> neighbors = graph.neighbors(vertex);
        for (V neighbor: vertices) {
            if (!neighbors.contains(neighbor) && !graph.containsEdge(neighbor)) {
                // If any neighbor does not have an edge, the subgraph is not a clique
                return false;
            }
        }
    }

    // If all checks pass, the subgraph is a clique
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    int n = vertices.size();
    if (n <= 1) return true;

    List<V> sortedVertices = new ArrayList<>(vertices);
    Collections.sort(sortedVertices);

    for (int i = 0; i < n - 1; i++) {
        V v1 = sortedVertices.get(i);
        for (int j = i + 1; j < n; j++) {
            V v2 = sortedVertices.get(j);
            if (!graph.containsEdge(v1, v2)) return false;
        }
    }

    return true;
}

