    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Create a reference variable to store the result
    StringBuilder result = new StringBuilder(pathComponents[0]);

    // Process the relative path components
    for (int i = 1; i < relativePathComponents.length; i++) {
        String component = relativePathComponents[i];
        if ("..".equals(component)) {
            // Go up one level
            if (result.length() == 0) {
                throw new IllegalArgumentException("Invalid relative path");
            }
            result.deleteCharAt(result.length() - 1);
        } else if (!"".equals(component)) {
            // Go down one level or include the component in the path
            result.append('/');
            result.append(component);
        }
    }

    // Append any remaining path components at the end
    for (int i = i; i < pathComponents.length; i++) {
        if (!"".equals(pathComponents[i]) && !"..".equals(pathComponents[i])) {
            result.append('/');
            result.append(pathComponents[i]);
        }
    }

    return result.toString();
}

